(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const W = 3200, H = 3200, TAU = Math.PI * 2;
  const $ = id => document.getElementById(id);
  let vw = 0, vh = 0, dpr = 1, last = performance.now(), elapsed = 0, day = 1;
  let timeOfDay = 0.34, toastTimer = 0, feedTimer = 0, paused = false;
  const keys = new Set(), mouse = {x: 0, y: 0, down: false};
  const world = {nodes: [], decor: [], enemies: [], buildings: [], companions: [], particles: []};
  const player = {x: W / 2, y: H / 2, vx: 0, vy: 0, angle: -0.5, hp: 100, stamina: 100, attack: 0, hurt: 0, invuln: 0, sprint: false};
  const bag = {wood: 8, stone: 4, fiber: 2, berries: 3};
  const slotData = [{name:'Stone axe',type:'tool'},{name:'Torch',type:'light'},{name:'Wood spear',type:'weapon'},{name:'Wood wall',type:'wall'},{name:'Campfire',type:'fire'},{name:'Empty',type:'empty'}];
  let selected = 0, buildMode = false, pointer = {x:0,y:0}, gameClock = 8.23;
  const rand = (() => { let s = 928361; return () => {s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296;} })();
  const clamp = (v,a,b) => Math.max(a, Math.min(b,v));
  const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
  const palette = ['#566d43','#667a4a','#526a40','#71804c','#5a7043'];
  function resize(){
    dpr = Math.min(2, window.devicePixelRatio || 1); vw = innerWidth; vh = innerHeight;
    canvas.width = Math.floor(vw*dpr); canvas.height = Math.floor(vh*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  addEventListener('resize',resize); resize();
  function generateWorld(){
    for(let i=0;i<1450;i++){
      const x=rand()*W,y=rand()*H, r=16+rand()*105;
      world.decor.push({x,y,r,color:palette[(rand()*palette.length)|0],alpha:.035+rand()*.07,kind:rand()});
    }
    for(let i=0;i<270;i++){
      let x=100+rand()*(W-200),y=100+rand()*(H-200);
      if(Math.hypot(x-player.x,y-player.y)<125) {i--;continue;}
      let type; const n=rand(); type=n<.49?'tree':n<.68?'rock':n<.88?'bush':'tree';
      world.nodes.push({x,y,type,hp:1,variant:rand(),scale:.75+rand()*.65,seed:rand(),alive:true});
    }
    for(let i=0;i<17;i++){
      const a=rand()*TAU,r=390+rand()*1040;
      world.enemies.push({x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,type:rand()<.72?'crawler':'wraith',hp:rand()<.72?3:4,speed:rand()<.72?27:34,attack:0,phase:rand()*TAU,alive:true});
    }
    world.companions=[{x:player.x-235,y:player.y+125,name:'Marlow',initial:'M',color:'#b18a63',phase:0},{x:player.x+320,y:player.y-170,name:'Rook',initial:'R',color:'#8194a2',phase:2}];
    // Little clearings and a broken trail give the wilderness a sense of scale.
    for(let i=0;i<42;i++){let x=rand()*W,y=rand()*H;world.decor.push({x,y,r:15+rand()*24,color:'#c0a76e',alpha:.12,kind:2});}
  }
  generateWorld();
  function feed(text){const f=$('feed');const line=document.createElement('div');line.className='feed-line';line.innerHTML='<span class="feed-icon">✦</span><span></span>';line.lastChild.textContent=text;f.appendChild(line);while(f.children.length>3)f.firstChild.remove();feedTimer=7;}
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=2.2;}
  function addParticle(x,y,color,n=8){for(let i=0;i<n;i++){const a=rand()*TAU,s=20+rand()*95;world.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+rand()*.55,max:.9,color,size:2+rand()*3});}}
  function nearestNode(max=92){let best=null,bd=max;for(const n of world.nodes){if(!n.alive)continue;const d=dist(player,n);if(d<bd){bd=d;best=n;}}return best?{node:best,d:bd}:null;}
  function gather(){const near=nearestNode(105);if(!near){toast('Nothing close enough to gather');return;}const n=near.node;n.alive=false;let resource,amount;
    if(n.type==='tree'){resource='wood';amount=3+(rand()*3|0);}else if(n.type==='rock'){resource='stone';amount=2+(rand()*3|0);}else{resource=rand()<.56?'fiber':'berries';amount=resource==='fiber'?2+(rand()*2|0):2+(rand()*3|0);}
    bag[resource]+=amount;addParticle(n.x,n.y,n.type==='tree'?'#d7b783':n.type==='rock'?'#c5d0c8':'#abc77d',11);feed(`Gathered ${amount} ${resource}`);updateHUD();
  }
  function nearestEnemy(max=86){let best=null,bd=max;for(const e of world.enemies){if(!e.alive)continue;const d=dist(player,e);if(d<bd){bd=d;best=e;}}return best?{enemy:best,d:bd}:null;}
  function attack(){if(player.attack>0||player.stamina<7)return;player.attack=.34;player.stamina-=7;let hit=false;for(const e of world.enemies){if(!e.alive)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy);if(d<100&&Math.cos(Math.atan2(dy,dx)-player.angle)>.05){e.hp-=selected===2?2:1;hit=true;addParticle(e.x,e.y,'#eaa38a',7);if(e.hp<=0){e.alive=false;bag.berries+=1;if(rand()<.45)bag.stone++;feed('The creature fades into the undergrowth');updateHUD();}}}if(!hit)addParticle(player.x+Math.cos(player.angle)*46,player.y+Math.sin(player.angle)*46,'#ded4a9',3);}
  function placeBuilding(){const type=selected===3?'wall':selected===4?'fire':null;if(!type)return;const x=player.x+Math.cos(player.angle)*72,y=player.y+Math.sin(player.angle)*72;
    const cost=type==='wall'?{wood:4}:{wood:5,stone:2};
    if(Object.entries(cost).some(([k,v])=>bag[k]<v)){toast(type==='wall'?'Need 4 wood':'Need 5 wood + 2 stone');return;}
    if(world.buildings.some(b=>Math.hypot(x-b.x,y-b.y)<48)){toast('Too close to another structure');return;}
    Object.entries(cost).forEach(([k,v])=>bag[k]-=v);world.buildings.push({x,y,type,angle:player.angle});addParticle(x,y,'#d7c17f',12);feed(type==='fire'?'Campfire placed':'Wood wall placed');updateHUD();
  }
  function interact(){if(buildMode||selected>=3){placeBuilding();return;}const near=nearestNode(105);if(near){gather();return;}const enemy=nearestEnemy(100);if(enemy){attack();return;}toast('Nothing to interact with nearby');}
  function chooseSlot(i){selected=i;document.querySelectorAll('.slot').forEach((el,j)=>el.classList.toggle('active',j===i));if(i===3||i===4){buildMode=true;toast(i===3?'Wall selected · press E to place':'Campfire selected · press E to place');}else buildMode=false;}
  function updateHUD(){
    $('woodCount').textContent=bag.wood;$('stoneCount').textContent=bag.stone;$('fiberCount').textContent=bag.fiber;$('berryCount').textContent=bag.berries;
    $('healthFill').style.width=player.hp+'%';$('healthText').textContent=Math.ceil(player.hp);$('staminaFill').style.width=player.stamina+'%';$('staminaText').textContent=Math.ceil(player.stamina);
    const total=bag.wood+bag.stone+bag.fiber+bag.berries, pct=clamp(total/24*100,0,100);$('objectiveProgress').style.width=pct+'%';$('objectiveCount').textContent=`${Math.min(total,24)} / 24 resources`;
    if(total>=24){$('objectiveTitle').textContent='Ready for the long night';$('objectiveText').textContent='Your supplies are growing. Keep your fire close and stay together.';}
    const clockH=Math.floor(gameClock)%24,clockM=Math.floor((gameClock%1)*60);$('clock').textContent=`${String(clockH).padStart(2,'0')}:${String(clockM).padStart(2,'0')}`;
    $('season').textContent=`PINEFALL · DAY ${String(day).padStart(2,'0')}`;
    const near=world.nodes.filter(n=>n.alive&&n.type==='tree').sort((a,b)=>dist(player,a)-dist(player,b))[0];if(near)$('treeDistance').textContent=`${Math.round(dist(player,near)/10)}m away`;
  }
  function onKey(e){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(e.repeat)return;
    if(k==='e')interact();if(k===' '||k==='f')attack();if(k==='b'){buildMode=!buildMode;toast(buildMode?'Build mode · select a structure':'Build mode closed');}
    if(k>='1'&&k<='6')chooseSlot(+k-1);if(k==='escape')togglePause();if(k==='c')openModal('Crafting');
  }
  function onUp(e){keys.delete(e.key.toLowerCase());}
  addEventListener('keydown',onKey);addEventListener('keyup',onUp);
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top;if(e.pointerType==='mouse'&&mouse.down)aimAtPointer();});
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;aimAtPointer();if(e.button===0)attack();}});
  addEventListener('pointerup',()=>mouse.down=false);
  function aimAtPointer(){const cam=camera();player.angle=Math.atan2(pointer.y-(vh/2+(player.y-cam.y)),pointer.x-(vw/2+(player.x-cam.x)));}
  document.querySelectorAll('.slot').forEach((el,i)=>el.addEventListener('click',()=>chooseSlot(i)));
  $('craftButton').onclick=()=>openModal('Crafting');$('menuButton').onclick=togglePause;$('inviteButton').onclick=()=>{navigator.clipboard?.writeText($('roomCode').textContent).catch(()=>{});toast('Party code copied · invite your friends');};
  $('modalClose').onclick=closeModal;$('resumeButton').onclick=closeModal;

function camera(){return{x:clamp(player.x-vw/2,0,W-vw),y:clamp(player.y-vh/2,0,H-vh)};}
function roundedRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
function drawGround(cam){
  ctx.fillStyle='#455f3d';ctx.fillRect(0,0,vw,vh);
  // Soft, irregular color fields make the ground feel like a broad forest floor.
  for(const d of world.decor){const x=d.x-cam.x,y=d.y-cam.y;if(x<-d.r||y<-d.r||x>vw+d.r||y>vh+d.r)continue;
    ctx.globalAlpha=d.alpha;ctx.fillStyle=d.color;ctx.beginPath();ctx.ellipse(x,y,d.r*1.35,d.r*.8,d.kind*2,0,TAU);ctx.fill();ctx.globalAlpha=1;
  }
  // Moss, fern flecks and tiny flowers.
  const spacing=86,startX=Math.floor(cam.x/spacing)*spacing,startY=Math.floor(cam.y/spacing)*spacing;
  for(let x=startX;x<cam.x+vw+spacing;x+=spacing)for(let y=startY;y<cam.y+vh+spacing;y+=spacing){const seed=((x*7+y*13)%31+31)%31,px=x-cam.x+seed,py=y-cam.y+(seed*11%41);ctx.fillStyle=seed%5===0?'#d4c77c77':'#233c2c77';ctx.globalAlpha=.4;ctx.beginPath();ctx.arc(px,py,seed%5===0?1.7:1.2,0,TAU);ctx.fill();ctx.globalAlpha=1;}
  // Worn trails through the clearing near the homestead.
  ctx.save();ctx.translate(W/2-cam.x,H/2-cam.y);ctx.rotate(-.64);ctx.fillStyle='#b49b6430';ctx.beginPath();ctx.ellipse(80,40,360,35,0,0,TAU);ctx.fill();ctx.restore();
}
function shadow(x,y,rx,ry,alpha=.25){ctx.fillStyle=`rgba(10,18,12,${alpha})`;ctx.beginPath();ctx.ellipse(x+4,y+7,rx,ry,0,0,TAU);ctx.fill();}
function drawTree(n,x,y){const s=n.scale,lean=(n.variant-.5)*8;shadow(x,y,18*s,8*s,.35);ctx.save();ctx.translate(x,y);ctx.scale(s,s);
  ctx.fillStyle='#684f39';ctx.fillRect(-5,3,10,26);ctx.fillStyle='#93704a';ctx.fillRect(-3,4,3,23);
  const layers=[{x:0,y:-30,r:26,c:'#304c34'},{x:-5,y:-14,r:24,c:'#3b5c3c'},{x:7,y:-3,r:20,c:'#476940'}];
  layers.forEach((l,i)=>{ctx.fillStyle=l.c;ctx.beginPath();ctx.moveTo(l.x+lean*i*.25,l.y-35);ctx.lineTo(l.x-l.r,l.y+12);ctx.quadraticCurveTo(l.x,l.y+5,l.x+l.r,l.y+12);ctx.closePath();ctx.fill();ctx.fillStyle=['#486b46','#577649','#68834f'][i];ctx.beginPath();ctx.ellipse(l.x-5,l.y-9,l.r*.47,5,-.4,0,TAU);ctx.fill();});
  ctx.restore();}
function drawRock(n,x,y){const s=n.scale;shadow(x,y,16*s,7*s,.3);ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#717b70';ctx.beginPath();ctx.moveTo(-15,7);ctx.lineTo(-12,-7);ctx.lineTo(-3,-15);ctx.lineTo(9,-12);ctx.lineTo(17,-2);ctx.lineTo(12,9);ctx.closePath();ctx.fill();ctx.fillStyle='#9ca69a';ctx.beginPath();ctx.moveTo(-10,-5);ctx.lineTo(-3,-13);ctx.lineTo(7,-10);ctx.lineTo(1,-2);ctx.closePath();ctx.fill();ctx.fillStyle='#535e56';ctx.beginPath();ctx.ellipse(4,9,10,3,0,0,TAU);ctx.fill();ctx.restore();}
function drawBush(n,x,y){const s=n.scale;shadow(x,y,15*s,6*s,.26);ctx.save();ctx.translate(x,y);ctx.scale(s,s);[[0,-2,12,'#567849'],[-8,2,9,'#496d40'],[8,3,10,'#66874a']].forEach(q=>{ctx.fillStyle=q[3];ctx.beginPath();ctx.arc(q[0],q[1],q[2],0,TAU);ctx.fill();});for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#c16f61':'#cb7770';ctx.beginPath();ctx.arc(-7+i*5,-1+(i%2)*4,2,0,TAU);ctx.fill();}ctx.restore();}
function drawBuilding(b,cam){const x=b.x-cam.x,y=b.y-cam.y;shadow(x,y,26,10,.4);if(b.type==='wall'){ctx.save();ctx.translate(x,y);ctx.rotate(b.angle);ctx.fillStyle='#705237';ctx.fillRect(-25,-8,50,16);ctx.fillStyle='#a98251';for(let i=-21;i<25;i+=10){ctx.fillRect(i,-7,7,14);ctx.fillStyle='#795a3a';ctx.fillRect(i+7,-7,3,14);ctx.fillStyle='#a98251';}ctx.restore();}else{ctx.fillStyle='#5e4935';ctx.beginPath();ctx.ellipse(x,y+5,18,11,0,0,TAU);ctx.fill();ctx.strokeStyle='#a68b60';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(x,y+5,17,10,0,0,TAU);ctx.stroke();const flick=1+Math.sin(elapsed*8)*.13;ctx.fillStyle='#ef8950';ctx.beginPath();ctx.ellipse(x,y-3,6*flick,10*flick,0,0,TAU);ctx.fill();ctx.fillStyle='#ffe2a1';ctx.beginPath();ctx.ellipse(x,y-2,3,6,0,0,TAU);ctx.fill();}}
function drawPerson(x,y,color,angle,isPlayer=false,name=''){shadow(x,y,12,5,.36);ctx.save();ctx.translate(x,y);if(isPlayer){ctx.rotate(angle);ctx.strokeStyle='#d5ca9d';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(4,0);ctx.lineTo(19,0);ctx.stroke();ctx.fillStyle='#d7bc7c';ctx.beginPath();ctx.arc(20,0,3,0,TAU);ctx.fill();}ctx.fillStyle='#25362a';ctx.beginPath();ctx.ellipse(0,3,9,12,0,0,TAU);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-1,8,10,0,0,TAU);ctx.fill();ctx.fillStyle='#d9b795';ctx.beginPath();ctx.arc(0,-11,6,0,TAU);ctx.fill();ctx.fillStyle='#594634';ctx.beginPath();ctx.arc(0,-13,6,Math.PI,TAU);ctx.fill();if(isPlayer){ctx.strokeStyle='#d4c27e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,15,0,TAU);ctx.stroke();}ctx.restore();if(name){ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillStyle='#f0ead4';ctx.fillText(name,x,y-24);}}
function drawEnemy(e,cam){const x=e.x-cam.x,y=e.y-cam.y,pulse=1+Math.sin(elapsed*5+e.phase)*.08;shadow(x,y,12,5,.32);ctx.save();ctx.translate(x,y);ctx.scale(pulse,1);if(e.type==='wraith'){ctx.fillStyle='#6d9c9b';ctx.globalAlpha=.82;ctx.beginPath();ctx.arc(0,-3,10,Math.PI,TAU);ctx.lineTo(10,5);ctx.lineTo(3,2);ctx.lineTo(0,9);ctx.lineTo(-4,2);ctx.lineTo(-10,6);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#c9e8cc';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);}else{ctx.fillStyle='#554d40';ctx.beginPath();ctx.ellipse(0,0,12,8,-.25,0,TAU);ctx.fill();ctx.fillStyle='#766452';ctx.beginPath();ctx.arc(-2,-5,7,0,TAU);ctx.fill();ctx.fillStyle='#e98765';ctx.fillRect(-5,-6,2,2);ctx.fillRect(2,-6,2,2);ctx.strokeStyle='#51463b';ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*5,3);ctx.lineTo(i*8,9);ctx.stroke();}}ctx.restore();}
function drawParticles(dt,cam){world.particles=world.particles.filter(p=>p.life>0);for(const p of world.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x-cam.x,p.y-cam.y,p.size,0,TAU);ctx.fill();}ctx.globalAlpha=1;}

function drawMinimap(){const w=mini.width,h=mini.height;mctx.fillStyle='#314b37';mctx.fillRect(0,0,w,h);for(const n of world.nodes){if(!n.alive)continue;const x=n.x/W*w,y=n.y/H*h;mctx.fillStyle=n.type==='tree'?'#79925a':n.type==='rock'?'#aab0a0':'#b0a86c';mctx.globalAlpha=.72;mctx.fillRect(x,y,2,2);}mctx.globalAlpha=1;for(const b of world.buildings){mctx.fillStyle=b.type==='fire'?'#ffad62':'#bca26d';mctx.fillRect(b.x/W*w-2,b.y/H*h-2,4,4);}for(const c of world.companions){mctx.fillStyle=c.color;mctx.beginPath();mctx.arc(c.x/W*w,c.y/H*h,2.4,0,TAU);mctx.fill();}for(const e of world.enemies){if(e.alive&&dist(player,e)<420){mctx.fillStyle='#e07c69';mctx.fillRect(e.x/W*w-1,e.y/H*h-1,3,3);}}const px=player.x/W*w,py=player.y/H*h;mctx.fillStyle='#ead99d';mctx.beginPath();mctx.arc(px,py,4,0,TAU);mctx.fill();mctx.strokeStyle='#fff4c4';mctx.lineWidth=1;mctx.beginPath();mctx.arc(px,py,7,0,TAU);mctx.stroke();mctx.strokeStyle='#ffffff18';mctx.strokeRect(0,0,w,h);}
function render(dt){const cam=camera();ctx.clearRect(0,0,vw,vh);drawGround(cam);
  // Nearby resource silhouettes are drawn in depth order with survivors and structures.
  const items=[];for(const n of world.nodes){if(!n.alive)continue;const x=n.x-cam.x,y=n.y-cam.y;if(x<-70||y<-70||x>vw+70||y>vh+70)continue;items.push({y,draw:()=>n.type==='tree'?drawTree(n,x,y):n.type==='rock'?drawRock(n,x,y):drawBush(n,x,y)});}
  world.buildings.forEach(b=>items.push({y:b.y,draw:()=>drawBuilding(b,cam)}));world.companions.forEach(c=>items.push({y:c.y,draw:()=>drawPerson(c.x-cam.x,c.y-cam.y,c.color,0,false,c.name)}));world.enemies.forEach(e=>{if(e.alive&&e.x>cam.x-50&&e.x<cam.x+vw+50&&e.y>cam.y-50&&e.y<cam.y+vh+50)items.push({y:e.y,draw:()=>drawEnemy(e,cam)});});items.push({y:player.y,draw:()=>drawPerson(player.x-cam.x,player.y-cam.y,'#9b7955',player.angle,true)});items.sort((a,b)=>a.y-b.y);items.forEach(o=>o.draw());
  // Attack sweep arcs and selected build ghost.
  if(player.attack>0){const x=player.x-cam.x,y=player.y-cam.y;ctx.save();ctx.translate(x,y);ctx.rotate(player.angle);ctx.strokeStyle=`rgba(234,221,167,${player.attack/.34*.75})`;ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,49,-.8,.8);ctx.stroke();ctx.restore();}
  if(buildMode&&(selected===3||selected===4)){const x=player.x+Math.cos(player.angle)*72-cam.x,y=player.y+Math.sin(player.angle)*72-cam.y;ctx.globalAlpha=.6;if(selected===3){ctx.fillStyle='#d5bc83';ctx.fillRect(x-25,y-7,50,14);}else{ctx.fillStyle='#f8b969';ctx.beginPath();ctx.arc(x,y,12,0,TAU);ctx.fill();}ctx.globalAlpha=1;}
  // Golden daylight, then a soft cool night tint and atmospheric firefly sparks.
  const night=clamp((Math.sin((timeOfDay-.25)*TAU)+.2)*.75,0,.68);if(night>0){ctx.fillStyle=`rgba(10,18,40,${night})`;ctx.fillRect(0,0,vw,vh);}const dusk=clamp((timeOfDay>.68?(timeOfDay-.68)/.16:timeOfDay<.18?(.18-timeOfDay)/.18:0),0,1);if(dusk>.02){ctx.fillStyle=`rgba(176,91,51,${dusk*.11})`;ctx.fillRect(0,0,vw,vh);}
  for(const b of world.buildings){if(b.type!=='fire')continue;const sx=b.x-cam.x,sy=b.y-cam.y;if(Math.abs(sx-vw/2)<vw*.65&&Math.abs(sy-vh/2)<vh*.65){const g=ctx.createRadialGradient(sx,sy,7,sx,sy,140);g.addColorStop(0,'rgba(250,160,79,.16)');g.addColorStop(1,'rgba(250,160,79,0)');ctx.fillStyle=g;ctx.fillRect(sx-140,sy-140,280,280);}}
  if(player.hurt>0){ctx.fillStyle=`rgba(183,55,47,${player.hurt*.22})`;ctx.fillRect(0,0,vw,vh);}drawParticles(dt,cam);
  const close=nearestNode(94);const enemy=nearestEnemy(92);const el=$('interaction');if(close) {el.innerHTML=`<kbd>E</kbd> Gather ${close.node.type==='tree'?'wood':close.node.type==='rock'?'stone':'supplies'}`;el.style.display='block';}else if(enemy){el.innerHTML='<kbd>SPACE</kbd> Attack';el.style.display='block';}else el.style.display='none';
  const co=world.companions[0];$('coords').textContent=`N ${String(Math.floor(player.y/200)).padStart(2,'0')} · E ${String(Math.floor(player.x/200)).padStart(2,'0')}`;drawMinimap();
}
