function drawBuilding(b,cam){const x=b.x-cam.x,y=b.y-cam.y;shadow(x,y,26,10,.4);if(b.type==='wall'){ctx.save();ctx.translate(x,y);ctx.rotate(b.angle);ctx.fillStyle='#705237';ctx.fillRect(-25,-8,50,16);ctx.fillStyle='#a98251';for(let i=-21;i<25;i+=10){ctx.fillRect(i,-7,7,14);ctx.fillStyle='#795a3a';ctx.fillRect(i+7,-7,3,14);ctx.fillStyle='#a98251';}ctx.restore();}else{ctx.fillStyle='#5e4935';ctx.beginPath();ctx.ellipse(x,y+5,18,11,0,0,TAU);ctx.fill();ctx.strokeStyle='#a68b60';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(x,y+5,17,10,0,0,TAU);ctx.stroke();const f=1+Math.sin(elapsed*8)*.13;ctx.fillStyle='#ef8950';ctx.beginPath();ctx.ellipse(x,y-3,6*f,10*f,0,0,TAU);ctx.fill();ctx.fillStyle='#ffe2a1';ctx.beginPath();ctx.ellipse(x,y-2,3,6,0,0,TAU);ctx.fill();}}
function drawPerson(x,y,color,angle,isPlayer=false,name=''){shadow(x,y,12,5,.36);ctx.save();ctx.translate(x,y);if(isPlayer){ctx.rotate(angle);ctx.strokeStyle='#d5ca9d';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(4,0);ctx.lineTo(19,0);ctx.stroke();ctx.fillStyle='#d7bc7c';ctx.beginPath();ctx.arc(20,0,3,0,TAU);ctx.fill();}ctx.fillStyle='#25362a';ctx.beginPath();ctx.ellipse(0,3,9,12,0,0,TAU);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-1,8,10,0,0,TAU);ctx.fill();ctx.fillStyle='#d9b795';ctx.beginPath();ctx.arc(0,-11,6,0,TAU);ctx.fill();ctx.fillStyle='#594634';ctx.beginPath();ctx.arc(0,-13,6,Math.PI,TAU);ctx.fill();if(isPlayer){ctx.strokeStyle='#d4c27e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,15,0,TAU);ctx.stroke();}ctx.restore();if(name){ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillStyle='#f0ead4';ctx.fillText(name,x,y-24);}}
function drawEnemy(e,cam){const x=e.x-cam.x,y=e.y-cam.y,p=1+Math.sin(elapsed*5+e.phase)*.08;shadow(x,y,12,5,.32);ctx.save();ctx.translate(x,y);ctx.scale(p,1);if(e.type==='wraith'){ctx.fillStyle='#6d9c9b';ctx.globalAlpha=.82;ctx.beginPath();ctx.arc(0,-3,10,Math.PI,TAU);ctx.lineTo(10,5);ctx.lineTo(3,2);ctx.lineTo(0,9);ctx.lineTo(-4,2);ctx.lineTo(-10,6);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#c9e8cc';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);}else{ctx.fillStyle='#554d40';ctx.beginPath();ctx.ellipse(0,0,12,8,-.25,0,TAU);ctx.fill();ctx.fillStyle='#766452';ctx.beginPath();ctx.arc(-2,-5,7,0,TAU);ctx.fill();ctx.fillStyle='#e98765';ctx.fillRect(-5,-6,2,2);ctx.fillRect(2,-6,2,2);ctx.strokeStyle='#51463b';ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*5,3);ctx.lineTo(i*8,9);ctx.stroke();}}ctx.restore();}
function drawParticles(dt,cam){world.particles=world.particles.filter(p=>p.life>0);for(const p of world.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x-cam.x,p.y-cam.y,p.size,0,TAU);ctx.fill();}ctx.globalAlpha=1;}

