*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#14201c;color:#f1eee1;font-family:'DM Sans',sans-serif}
button{font:inherit;color:inherit}
.game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:#263a2d}
#world{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 35%,rgba(9,17,14,.18) 78%,rgba(8,13,12,.52) 130%);z-index:1}
.topbar{position:absolute;z-index:3;left:0;right:0;top:0;height:72px;padding:0 28px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(11,20,17,.9),rgba(12,21,17,.62));border-bottom:1px solid rgba(231,222,186,.14)}
.brand{display:flex;align-items:center;gap:11px;min-width:210px}
.brand-mark{width:37px;height:37px;border:1px solid rgba(200,177,106,.7);border-radius:11px;display:grid;place-items:center;color:#d4be79;font:700 21px 'Space Grotesk';background:linear-gradient(145deg,rgba(183,153,80,.22),rgba(30,49,38,.45));box-shadow:inset 0 0 14px #b69a3530}
.brand strong{font:700 16px 'Space Grotesk';letter-spacing:2.6px;display:block}
.brand small{font-size:8px;letter-spacing:2.3px;color:#a6a891;display:block;margin-top:3px}
.world-status{display:flex;align-items:center;gap:13px;font-size:10px;font-weight:700;letter-spacing:1.5px;color:#cccab7}
.world-status i{height:13px;width:1px;background:#ffffff35}
.world-status .weather{color:#d8d1b3}
