input.newString:
  function drawParticles(dt,cam){world.particles=world.particles.filter(p=>p.life>0);for(const p of world.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x-cam.x,p.y-cam.y,p.size,0,TAU);ctx.fill();}ctx.globalAlpha=1;}
  const recipes=[
    {name:'Field rations',icon:'◉',desc:'Restore 28 health',cost:{berries:3},action:()=>{player.hp=Math.min(100,player.hp+28);toast('A little strength returns');}},
    {name:'Stone hatchet',icon:'⚒',desc:'Improve your gathering tool',cost:{wood:5,stone:3},action:()=>{player.damage=2;toast('Stone hatchet crafted · attacks strengthened');}},
    {name:'Wooden spear',icon:'╱',desc:'A longer reach in a fight',cost:{wood:4,fiber:2},action:()=>{player.damage=Math.max(player.damage,2);toast('Wooden spear crafted');}},
    {name:'Campfire',icon:'♨',desc:'Light and warmth for the long night',cost:{wood:5,stone:2},action:()=>{selected=4;chooseSlot(4);toast('Campfire ready · press E to place');}}
  ];
  function canAfford(cost){return Object.entries(cost).every(([k,v])=>bag[k]>=v);}
  function costText(cost){return Object.entries(cost).map(([k,v])=>`${v} ${k}`).join(' · ');}
  function openModal(title='Crafting'){
    paused=true;const modal=$('modal');$('modalTitle').textContent=title;
    $('modalDesc').textContent=title==='Crafting'?'Turn what you find into what you need.':'Take a breath, survivor. The forest will wait.';
    const list=$('recipeList');list.innerHTML='';
    if(title==='Crafting')recipes.forEach(recipe=>{const row=document.createElement('div');row.className='recipe';const icon=document.createElement('span');icon.className='recipe-icon';icon.textContent=recipe.icon;const info=document.createElement('span');info.className='recipe-info';const name=document.createElement('b');name.textContent=recipe.name;const desc=document.createElement('small');desc.textContent=`${recipe.desc} · ${costText(recipe.cost)}`;info.append(name,desc);const btn=document.createElement('button');btn.textContent='CRAFT';btn.disabled=!canAfford(recipe.cost);btn.onclick=()=>{if(!canAfford(recipe.cost))return;Object.entries(recipe.cost).forEach(([k,v])=>bag[k]-=v);recipe.action();updateHUD();openModal('Crafting');};row.append(icon,info,btn);list.appendChild(row);});
    else{const note=document.createElement('div');note.className='recipe';note.innerHTML='<span class="recipe-icon">✧</span><span class="recipe-info"><b>Wilderness pause</b><small>WASD move · Shift sprint · E gather/build · Space attack · C craft</small></span>';list.appendChild(note);}
    $('resumeButton').textContent=title==='Crafting'?'BACK TO THE WILD':'RESUME JOURNEY';modal.classList.remove('hidden');
  }
  function closeModal(){$('modal').classList.add('hidden');paused=false;last=performance.now();}
  function togglePause(){if(!$('modal').classList.contains('hidden'))closeModal();else openModal('Paused');}
  function drawMinimap(){const w=mini.width,h=mini.height,sx=w/W,sy=h/H;mctx.clearRect(0,0,w,h);mctx.fillStyle='#334a39';mctx.fillRect(0,0,w,h);mctx.fillStyle='#b8a36a';for(const b of world.buildings){mctx.beginPath();mctx.arc(b.x*sx,b.y*sy,3,0,TAU);mctx.fill();}mctx.fillStyle='#759b72';for(const n of world.nodes){if(!n.alive)continue;mctx.fillRect(n.x*sx,n.y*sy,1.5,1.5);}mctx.fillStyle='#d27d69';for(const e of world.enemies){if(e.alive&&dist(player,e)<550){mctx.beginPath();mctx.arc(e.x*sx,e.y*sy,2,0,TAU);mctx.fill();}}mctx.fillStyle='#e6d38d';mctx.beginPath();mctx.arc(player.x*sx,player.y*sy,3.3,0,TAU);mctx.fill();mctx.strokeStyle='#fff0bc';mctx.lineWidth=1;mctx.beginPath();mctx.moveTo(player.x*sx,player.y*sy);mctx.lineTo((player.x+Math.cos(player.angle)*46)*sx,(player.y+Math.sin(player.angle)*46)*sy);mctx.stroke();$('coords').textContent=`N ${String(Math.floor(player.y/100)%32).padStart(2,'0')} · E ${String(Math.floor(player.x/100)%32).padStart(2,'0')}`;}
  function update(dt){if(paused)return;elapsed+=dt;gameClock=(8.23+elapsed/110)%24;timeOfDay=gameClock/24;if(gameClock<.03&&elapsed>1){day++;feed(`Day ${day} breaks over Pinefall`);}player.attack=Math.max(0,player.attack-dt);player.hurt=Math.max(0,player.hurt-dt);player.invuln=Math.max(0,player.invuln-dt);
    let ix=joyX,iy=joyY;if(keys.has('w')||keys.has('arrowup'))iy--;if(keys.has('s')||keys.has('arrowdown'))iy++;if(keys.has('a')||keys.has('arrowleft'))ix--;if(keys.has('d')||keys.has('arrowright'))ix++;const mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag;}const sprint=(keys.has('shift')||player.sprint)&&player.stamina>2&&mag>.1;const speed=sprint?210:142;if(sprint)player.stamina=Math.max(0,player.stamina-24*dt);else player.stamina=Math.min(100,player.stamina+14*dt);player.vx+=(ix*speed-player.vx)*Math.min(1,dt*10);player.vy+=(iy*speed-player.vy)*Math.min(1,dt*10);if(mag<.05){player.vx*=Math.max(0,1-dt*7);player.vy*=Math.max(0,1-dt*7);}if(mag>.1&&Math.abs(joyX)+Math.abs(joyY)>.3)player.angle=Math.atan2(iy,ix);player.x=clamp(player.x+player.vx*dt,24,W-24);player.y=clamp(player.y+player.vy*dt,24,H-24);
    world.companions.forEach((c,i)=>{const a=elapsed*.45+c.phase,targetX=player.x+Math.cos(a+i*Math.PI)*75,targetY=player.y+Math.sin(a+i*Math.PI)*57;c.x+=(targetX-c.x)*Math.min(1,dt*.8);c.y+=(targetY-c.y)*Math.min(1,dt*.8);});
    for(const e of world.enemies){if(!e.alive)continue;e.attack=Math.max(0,e.attack-dt);const d=dist(player,e);if(d<360){const a=Math.atan2(player.y-e.y,player.x-e.x);e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt;if(d<24&&e.attack<=0&&player.invuln<=0){e.attack=1.15;player.hp=Math.max(0,player.hp-9);player.invuln=.6;player.hurt=.25;addParticle(player.x,player.y,'#d77965',5);if(player.hp<=0){player.hp=65;player.x=W/2;player.y=H/2;bag.berries=Math.max(0,bag.berries-2);toast('You wake by the old trail · some berries lost');}}}}
    if(Math.random()<dt*.018&&world.enemies.filter(e=>e.alive).length<17){const a=rand()*TAU,r=500+rand()*240;world.enemies.push({x:clamp(player.x+Math.cos(a)*r,40,W-40),y:clamp(player.y+Math.sin(a)*r,40,H-40),type:rand()<.72?'crawler':'wraith',hp:3,speed:27,attack:0,phase:rand()*TAU,alive:true});}
    if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show');}updateHUD();
  }
